import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.CqGPl1zp.js";const n="/newx-doc/assets/%E8%A1%A8%E5%85%B3%E7%B3%BB.BXQKX5E5.svg",d="/newx-doc/assets/%E6%96%87%E4%BB%B6%E7%AE%A1%E7%90%86.BJ0QxE3e.png",h="/newx-doc/assets/%E4%B8%8A%E4%BC%A0%E6%96%87%E4%BB%B6.BuAYEEtN.png",l="/newx-doc/assets/%E6%96%87%E4%BB%B6%E9%A2%84%E8%A7%88.C1U1AmF1.png",p="/newx-doc/assets/%E5%A4%8D%E5%88%B6%E6%96%87%E4%BB%B6.Buy6mzRH.png",k="/newx-doc/assets/%E5%9B%9E%E6%94%B6%E7%AB%99.D4N_TDim.png",o="/newx-doc/assets/%E5%85%B1%E4%BA%AB%E6%9D%83%E9%99%90.CiFjMpFh.png",r="/newx-doc/assets/%E6%96%87%E4%BB%B6%E6%94%B6%E8%97%8F.DjfT81EL.png",u=JSON.parse('{"title":"【办公】企业云盘","description":"","frontmatter":{},"headers":[],"relativePath":"oa/file.md","filePath":"oa/file.md","lastUpdated":null}'),E={name:"oa/file.md"};function c(g,s,F,y,_,A){return a(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="【办公】企业云盘" tabindex="-1">【办公】企业云盘 <a class="header-anchor" href="#【办公】企业云盘" aria-label="Permalink to &quot;【办公】企业云盘&quot;">​</a></h1><p>企业云盘，由 <code>yudao-module-oa</code> 后端模块的 <code>file</code> 包实现，前端实现在 <code>@/views/oa/file</code> 目录。</p><p>企业云盘以文件节点为中心，文件夹和文件共用一张表。用户可以维护个人文件、查看共享文件，并通过用户或部门授权控制查看、下载和编辑范围。</p><p>本文涉及表如下图所示：</p><p><img src="'+n+'" alt="企业云盘表关系"></p><h2 id="_1-文件管理" tabindex="-1">1. 文件管理 <a class="header-anchor" href="#_1-文件管理" aria-label="Permalink to &quot;1. 文件管理&quot;">​</a></h2><p>文件管理，由 OaFileNodeController 提供接口（<code>/oa/file-node</code>）。</p><h3 id="_1-1-主表表结构" tabindex="-1">1.1 主表表结构 <a class="header-anchor" href="#_1-1-主表表结构" aria-label="Permalink to &quot;1.1 主表表结构&quot;">​</a></h3><blockquote><p>省略 creator/create_time/updater/update_time/deleted/tenant_id 等通用字段</p></blockquote><p>文件节点表 <code>oa_file_node</code>，用一张表保存文件夹和文件，通过 <code>parent_id</code> 组成目录树：</p><div class="language-SQL vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oa_file_node</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `parent_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;父目录编号，根目录为 0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `type`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;节点类型&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `name`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;节点名称&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `extension`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;扩展名&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `category`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;文件分类&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `size`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;文件大小，单位字节&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `url`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2048</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;文件访问地址&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `dept_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;所属部门编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `status`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;节点状态&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `idx_parent_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`tenant_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`parent_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `idx_creator`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`tenant_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`creator`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `idx_creator_status_category`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`tenant_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`creator`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`status`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`category`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB COMMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;云盘文件节点&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>① <code>parent_id</code> <strong>自关联</strong>本表的 <code>id</code> 字段，根目录为 <code>0</code>（<code>OaFileNodeDO.PARENT_ID_ROOT</code>）。<code>idx_parent_id</code> 支撑按父目录列子节点；同目录同名由 OaFileNodeServiceImpl 的 <code>validateName</code> 校验，冲突抛出重名异常。</p><p>② 枚举 <code>type</code> 节点类型（<code>OaFileNodeTypeEnum</code>）：</p><table tabindex="0"><thead><tr><th>值</th><th>枚举</th><th>说明</th></tr></thead><tbody><tr><td><code>0</code></td><td><code>FOLDER</code></td><td>文件夹</td></tr><tr><td><code>1</code></td><td><code>FILE</code></td><td>文件</td></tr></tbody></table><p>③ 枚举 <code>category</code> 文件分类（<code>OaFileCategoryEnum</code>），对应字典 <code>oa_file_category</code>。<strong>文件夹的 <code>category</code> 为空</strong>；文件在创建 / 重命名时由 <code>OaFileCategoryEnum.getByExtension</code> 根据扩展名计算：</p><table tabindex="0"><thead><tr><th>值</th><th>枚举</th><th>说明</th></tr></thead><tbody><tr><td><code>1</code></td><td><code>IMAGE</code></td><td>图片</td></tr><tr><td><code>2</code></td><td><code>DOCUMENT</code></td><td>文档</td></tr><tr><td><code>3</code></td><td><code>VIDEO</code></td><td>视频</td></tr><tr><td><code>4</code></td><td><code>AUDIO</code></td><td>音频</td></tr><tr><td><code>5</code></td><td><code>ARCHIVE</code></td><td>压缩包</td></tr><tr><td><code>6</code></td><td><code>OTHER</code></td><td>其他</td></tr></tbody></table><p>④ <code>dept_id</code> 关联 <code>system_dept</code> 表的 <code>id</code> 字段，<strong>创建时快照</strong>所属人当时的部门（<code>adminUserApi.getUser(userId).getDeptId()</code>），后续调岗不回写历史节点。账号归属仍用通用字段 <code>creator</code>（关联 <code>system_users</code>）。</p><p>⑤ <code>status</code> 是节点业务状态，详见 <a href="#_1-2-状态流转">§1.2 状态流转</a>。<strong>移入回收站改 <code>status</code>，彻底删除才置 <code>deleted</code></strong>；彻底删除<strong>不删除 Infra 物理文件</strong>。</p><p>⑥ <strong>列表接口不返回 <code>url</code></strong>（统一置 <code>null</code>）。详情 <code>getFileNode</code> 在具备 <strong>DOWNLOAD 及以上</strong>权限时，才对文件签发临时地址（<code>fileApi.presignGetUrl</code>）。容量统计（<code>get-storage</code> / <code>selectSumSizeByCreatorAndType</code>）<strong>含回收站内尚未彻底删除的文件</strong>。</p><p>列表范围由 <code>OaFileScopeEnum</code> 区分：</p><table tabindex="0"><thead><tr><th>值</th><th>枚举</th><th>说明</th></tr></thead><tbody><tr><td><code>my</code></td><td><code>MY</code></td><td>我的文件</td></tr><tr><td><code>shared</code></td><td><code>SHARED</code></td><td>共享文件</td></tr><tr><td><code>favorite</code></td><td><code>FAVORITE</code></td><td>我的收藏</td></tr><tr><td><code>recycle</code></td><td><code>RECYCLE</code></td><td>回收站</td></tr></tbody></table><hr><p>该表关联两张业务表：</p><ul><li><code>oa_file_permission</code>（共享权限）：在【共享设置】中维护，保存用户 / 部门授权。</li><li><code>oa_file_favorite</code>（文件收藏）：在【收藏】中维护，保存个人收藏入口。</li></ul><h3 id="_1-2-状态流转" tabindex="-1">1.2 状态流转 <a class="header-anchor" href="#_1-2-状态流转" aria-label="Permalink to &quot;1.2 状态流转&quot;">​</a></h3><p>节点状态由 OaFileNodeServiceImpl 控制，状态字段为 <code>status</code>，对应枚举 <code>OaFileNodeStatusEnum</code>：</p><table tabindex="0"><thead><tr><th>状态值</th><th>枚举</th><th>说明</th><th>可执行操作</th></tr></thead><tbody><tr><td><code>0</code></td><td><code>NORMAL</code></td><td>正常</td><td>查看、编辑、移动、回收、共享、收藏</td></tr><tr><td><code>1</code></td><td><code>RECYCLED</code></td><td>回收站</td><td>恢复、彻底删除</td></tr></tbody></table><p>状态流转说明</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建(createFileNode) ──→ 正常(0) ──回收(recycleFileNode)──→ 回收站(1)</span></span>\n<span class="line"><span>                              ↑                              │</span></span>\n<span class="line"><span>                              └────恢复(restoreFileNode)──────┘</span></span>\n<span class="line"><span>                                                     │</span></span>\n<span class="line"><span>                                                     └──彻底删除(deleteFileNode)</span></span>\n<span class="line"><span>                                                        （须先在回收站；级联权限与收藏；</span></span>\n<span class="line"><span>                                                         不删 Infra 物理文件）</span></span></code></pre></div><ul><li><strong>创建</strong>（<code>createFileNode</code>）：状态<strong>固定初始化为 <code>正常(0)</code></strong>，并写入部门快照；文件分类由扩展名计算。</li><li><strong>回收</strong>（<code>recycleFileNode</code>）：<code>正常(0)</code> → <code>回收站(1)</code>。<strong>只改当前节点</strong>，不级联改子节点状态；须本人节点（<code>validateOwner</code>）。</li><li><strong>恢复</strong>（<code>restoreFileNode</code>）：<code>回收站(1)</code> → <code>正常(0)</code>。<strong>父目录必须可用</strong>（非根时 <code>validateFileNodePermission</code> 要求父目录可编辑且祖先均为正常）；不改变此前单独回收的子节点。父目录仍在回收站时需先恢复父目录，否则抛出 <code>FILE_NODE_NOT_AVAILABLE</code> 等异常。</li><li><strong>彻底删除</strong>（<code>deleteFileNode</code>）：节点<strong>必须已在回收站</strong>，否则抛出 <code>FILE_NODE_NOT_RECYCLED</code>。按层收集整棵子树，逻辑删除节点，并级联 <code>deleteFilePermissionsByNodeIds</code>、<code>deleteFileFavoritesByNodeIds</code>；<strong>不删除底层 Infra 存储文件</strong>。</li><li>访问正常节点时，<code>validateFileNodeAvailable</code> 会校验<strong>自身及全部祖先</strong>均为 <code>正常(0)</code>，防止通过收藏、搜索或直接编号访问回收目录下的文件。</li></ul><h3 id="_1-3-管理后台" tabindex="-1">1.3 管理后台 <a class="header-anchor" href="#_1-3-管理后台" aria-label="Permalink to &quot;1.3 管理后台&quot;">​</a></h3><p>对应 [OA 办公协同 -&gt; 企业云盘] 菜单，对应 <code>yudao-ui-admin-vue3</code> 项目的 <code>@/views/oa/file</code> 目录。</p><h4 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to &quot;列表&quot;">​</a></h4><p>在本人文件、共享文件、收藏和回收站之间切换（<code>scope = my / shared / favorite / recycle</code>），按名称、类型和创建时间筛选。容量统计由 <code>GET /oa/file-node/get-storage</code> 提供。</p><p><img src="'+d+'" alt="管理后台 - 文件管理"></p><h4 id="新建文件夹与上传" tabindex="-1">新建文件夹与上传 <a class="header-anchor" href="#新建文件夹与上传" aria-label="Permalink to &quot;新建文件夹与上传&quot;">​</a></h4><p>点击【新建文件夹】打开 <code>OaFileNodeForm.vue</code>，填写名称后保存。文件通过 <code>OaFileUpload.vue</code> 上传，再调用 <code>POST /oa/file-node/create</code> 保存文件节点；同目录不能存在重名节点。</p><p><img src="'+h+'" alt="管理后台 - 上传文件"></p><h4 id="预览与下载" tabindex="-1">预览与下载 <a class="header-anchor" href="#预览与下载" aria-label="Permalink to &quot;预览与下载&quot;">​</a></h4><p>点击文件进入 <code>OaFilePreview.vue</code>。详情接口 <code>/oa/file-node/get</code> 根据权限返回可用信息；具备下载权限时才显示可下载地址。</p><p><img src="'+l+'" alt="管理后台 - 文件预览"></p><h4 id="重命名与移动" tabindex="-1">重命名与移动 <a class="header-anchor" href="#重命名与移动" aria-label="Permalink to &quot;重命名与移动&quot;">​</a></h4><p>重命名调用 <code>PUT /oa/file-node/update-name</code>。移动时选择目标目录，调用 <code>PUT /oa/file-node/update-parent</code>；<strong>仅允许移动本人节点</strong>，不能把文件夹移动到自身或其子目录中。</p><h4 id="复制" tabindex="-1">复制 <a class="header-anchor" href="#复制" aria-label="Permalink to &quot;复制&quot;">​</a></h4><p><img src="'+p+'" alt="管理后台 - 复制文件"></p><h4 id="回收、恢复与彻底删除" tabindex="-1">回收、恢复与彻底删除 <a class="header-anchor" href="#回收、恢复与彻底删除" aria-label="Permalink to &quot;回收、恢复与彻底删除&quot;">​</a></h4><p>移入回收站调用 <code>/oa/file-node/recycle</code>。在回收站点击【恢复】回到原位置，若父目录也被回收，需要先恢复父目录。点击【彻底删除】会清理节点及子树、共享和收藏关系；底层存储文件不会由此接口直接删除。</p><p><img src="'+k+'" alt="管理后台 - 回收站"></p><h2 id="_2-共享权限" tabindex="-1">2. 共享权限 <a class="header-anchor" href="#_2-共享权限" aria-label="Permalink to &quot;2. 共享权限&quot;">​</a></h2><p>共享权限，由 OaFilePermissionController 提供接口（<code>/oa/file-permission</code>）。</p><h3 id="_2-1-主表表结构" tabindex="-1">2.1 主表表结构 <a class="header-anchor" href="#_2-1-主表表结构" aria-label="Permalink to &quot;2.1 主表表结构&quot;">​</a></h3><blockquote><p>省略 creator/create_time/updater/update_time/deleted/tenant_id 等通用字段</p></blockquote><p>共享权限表 <code>oa_file_permission</code>，保存节点授权给哪些用户或部门及其权限级别：</p><div class="language-SQL vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oa_file_permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `node_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;共享节点编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `subject_type`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;共享主体类型&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `subject_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;共享主体编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `level`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;共享权限级别&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `inherit`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;是否继承到子目录&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `expire_time`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;权限到期时间&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `idx_node_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`tenant_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`node_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB COMMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;云盘共享权限&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>① <code>node_id</code> 关联 <code>oa_file_node</code> 表的 <code>id</code> 字段。维护共享前须具备该节点的 <strong>MANAGE</strong> 权限（<code>validateFileNodePermission(..., MANAGE)</code>）。<code>idx_node_id</code> 支撑按节点查授权列表。</p><p>② 枚举 <code>subject_type</code> 共享主体类型（<code>OaFileSubjectTypeEnum</code>），对应字典 <code>oa_file_subject_type</code>：</p><table tabindex="0"><thead><tr><th>值</th><th>枚举</th><th>说明</th></tr></thead><tbody><tr><td><code>1</code></td><td><code>USER</code></td><td>用户</td></tr><tr><td><code>2</code></td><td><code>DEPT</code></td><td>部门</td></tr></tbody></table><p><code>subject_id</code> 在 <code>USER</code> 时关联 <code>system_users</code> 表的 <code>id</code> 字段，在 <code>DEPT</code> 时关联 <code>system_dept</code> 表的 <code>id</code> 字段；保存时分别由 <code>adminUserApi.validateUser</code>、<code>deptApi.validateDeptList</code> 校验。</p><p>③ 枚举 <code>level</code> 共享权限级别（<code>OaFilePermissionLevelEnum</code>），对应字典 <code>oa_file_permission_level</code>：</p><table tabindex="0"><thead><tr><th>值</th><th>枚举</th><th>说明</th></tr></thead><tbody><tr><td><code>1</code></td><td><code>READ</code></td><td>只读</td></tr><tr><td><code>2</code></td><td><code>DOWNLOAD</code></td><td>下载</td></tr><tr><td><code>3</code></td><td><code>EDIT</code></td><td>编辑</td></tr><tr><td><code>4</code></td><td><code>MANAGE</code></td><td>管理</td></tr></tbody></table><p>权限计算（<code>getLevel</code>）规则：<strong>本人创建的节点直接视为 <code>MANAGE(4)</code></strong>；他人节点取用户授权与部门授权的最高级别，祖先节点仅在 <code>inherit = true</code> 且未过期（<code>expire_time</code>）时向下传递。移动、回收、彻底删除等操作额外要求<strong>本人节点</strong>（<code>validateOwner</code>）。</p><h3 id="_2-2-管理后台" tabindex="-1">2.2 管理后台 <a class="header-anchor" href="#_2-2-管理后台" aria-label="Permalink to &quot;2.2 管理后台&quot;">​</a></h3><p>对应 [OA 办公协同 -&gt; 企业云盘] 菜单，对应 <code>yudao-ui-admin-vue3</code> 项目的 <code>@/views/oa/file</code> 目录。共享权限没有独立菜单，在文件列表的【共享设置】弹窗中维护。</p><h4 id="设置共享" tabindex="-1">设置共享 <a class="header-anchor" href="#设置共享" aria-label="Permalink to &quot;设置共享&quot;">​</a></h4><p>在文件列表打开【共享设置】，由 <code>OaFilePermissionList.vue</code> 展示授权。点击【新增】打开 <code>OaFilePermissionForm.vue</code>，选择用户或部门、权限级别、继承设置和到期时间，调用 <code>POST /oa/file-permission/save</code>。</p><p><img src="'+o+'" alt="管理后台 - 共享权限"></p><h4 id="修改与取消共享" tabindex="-1">修改与取消共享 <a class="header-anchor" href="#修改与取消共享" aria-label="Permalink to &quot;修改与取消共享&quot;">​</a></h4><p>在共享设置中修改权限或点击【取消共享】。取消后，接收人通过该条授权获得的访问能力失效；如果仍有其他有效授权，按剩余授权计算权限。</p><h2 id="_3-文件收藏" tabindex="-1">3. 文件收藏 <a class="header-anchor" href="#_3-文件收藏" aria-label="Permalink to &quot;3. 文件收藏&quot;">​</a></h2><p>文件收藏，由 OaFileFavoriteController 提供接口（<code>/oa/file-favorite</code>）。</p><h3 id="_3-1-主表表结构" tabindex="-1">3.1 主表表结构 <a class="header-anchor" href="#_3-1-主表表结构" aria-label="Permalink to &quot;3.1 主表表结构&quot;">​</a></h3><blockquote><p>省略 creator/create_time/updater/update_time/deleted/tenant_id 等通用字段</p></blockquote><p>收藏表 <code>oa_file_favorite</code>，保存「用户收藏了哪个节点」的关系：</p><div class="language-SQL vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oa_file_favorite</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `node_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;收藏节点编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `user_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;收藏用户编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `idx_node_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`tenant_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`node_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `idx_user_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`tenant_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`user_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB COMMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;云盘收藏&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>① <code>node_id</code> 关联 <code>oa_file_node</code> 表的 <code>id</code> 字段，<code>user_id</code> 关联 <code>system_users</code> 表的 <code>id</code> 字段。收藏前须至少具备 <strong>READ</strong> 权限（<code>createFileFavorite</code> → <code>validateFileNodePermission(..., READ)</code>）。</p><p>② 收藏<strong>只保存个人入口</strong>，不复制文件，也不额外增加访问权限；进入收藏列表时仍会校验节点与祖先是否可用、共享是否仍然有效。彻底删除节点时，由 <code>deleteFileFavoritesByNodeIds</code> 级联清理。</p><h3 id="_3-2-管理后台" tabindex="-1">3.2 管理后台 <a class="header-anchor" href="#_3-2-管理后台" aria-label="Permalink to &quot;3.2 管理后台&quot;">​</a></h3><p>对应 [OA 办公协同 -&gt; 企业云盘] 菜单，对应 <code>yudao-ui-admin-vue3</code> 项目的 <code>@/views/oa/file</code> 目录。文件收藏没有独立菜单，在文件列表切换到【我的收藏】页签查看。</p><h4 id="收藏与取消收藏" tabindex="-1">收藏与取消收藏 <a class="header-anchor" href="#收藏与取消收藏" aria-label="Permalink to &quot;收藏与取消收藏&quot;">​</a></h4><p>在可访问文件上执行收藏或取消收藏，分别调用 <code>POST /oa/file-favorite/create</code>、<code>DELETE /oa/file-favorite/delete</code>。进入收藏列表时仍需校验文件和共享权限是否有效。</p><p><img src="'+r+'" alt="管理后台 - 文件收藏"></p>',81)])])}const B=i(E,[["render",c]]);export{u as __pageData,B as default};
